input.command:
cat > utils/request.ts <<'EOF'
/**
 * Clone a request without ever throwing. If `clone()` fails (e.g. the body is
 * disturbed or locked), a bodyless copy of the request is returned instead.
 */
export function safeCloneRequest(request?: Request): Request | undefined {
	if (!request) {
		return undefined;
	}
	try {
		return request.clone();
	} catch {
		const init: RequestInit = {
			method: request.method,
			headers: new Headers(request.headers),
		};
		const optional = [
			"cache",
			"credentials",
			"integrity",
			"keepalive",
			"mode",
			"redirect",
			"referrer",
			"referrerPolicy",
			"signal",
		] as const;
		for (const key of optional) {
			try {
				const value = request[key];
				if (value !== undefined) {
					(init as Record<string, unknown>)[key] = value;
				}
			} catch {}
		}
		try {
			return new Request(request.url, init);
		} catch {
			// some runtimes reject certain options; retry with the essentials
			return new Request(request.url, {
				method: request.method,
				headers: new Headers(request.headers),
			});
		}
	}
}
EOF
sed -i 's/ctx\.request?\.clone()/safeCloneRequest(ctx.request)/' api/routes/{email-verification,sign-in,sign-up}.ts
for f in email-verification sign-in sign-up; do
 sed -i '0,/^import /s//import { safeCloneRequest } from "..\/..\/utils\/request";\nimport /' api/routes/$f.ts; done
git diff --stat; cd .. && npx tsc --noEmit -p . 2>&1 | head

